INGREDIENT = re.compile(r'^(?:[•▫▪·📌\-]\s*)?(?:для (?:соуса|теста|начинки|крема|глазури|пропитки|сборки)|начинка\s*\d?|глазурь|тесто|пропитка|крем|заправка|соус|салат|картофель|пюре|рыба|минтай|хек|треска|филе|фарш|ананас|сыр|творог|яйц|желт|белок|сметан|слив|молок|мук|крахмал|разрыхл|соль|сахар|перец|чеснок|паприк|куриц|курин|бедро|грудк|масло|лук|огур|томат|помидор|морков|зелень|укроп|петруш|кинз|шпинат|брокк|тыкв|апельсин|мандарин|цедра|изюм|груш|корица|тростник|кокос|ванил|желат|ягод|струж|тунец|рисов|соев|кунжут|терияки|соус|рис|булгур|фунчоз|индейк|шокол|кревет|снежн|икра|японск|шрирач|чипс|тартал|макарон|фета|лёгк|легк|пшенич|мак\b|подсласт|лимон|мёд|мед\b|лепеш|лепёш|тортиль|хлеб|сёмг|семг|форел|багет|прошу|сладк|виноград|орех|тимьян|кляр|оливк|смесь орех|салатный микс|гренк|йогурт|карри|пита|хмели|вода|бульон|печень|печён|печен|псиллиум|семена|листья|печенье|карамель|майонез|тесто фило|сухой|чернослив|шампиньон|консерв|слабосол|сок|горчиц|яблочн|рисовый|соус ким|тамбов|сметана|кокосовое|растительное)', re.I)
ACTION = re.compile(r'(нарез|обжар|смеш|соедин|выпека|выпечь|запека|запечь|разогре|вылож|выклады|добав|отправ|сформ|формир|отвар|варим|варить|готовить|готовим|покры|растоп|раскат|завер|заворач|погру|замоч|замач|разлив|разлить|залить|залива|слож|сверн|сворач|перелож|уберите|убира|промаз|размя|чистим|натира|натер|раздав|пробить|взбить|взбей|разрез|подсуш|томить|томим|тушить|тушим|постав|помест|накры|протыка|очист|подготов|жарить|жарится|запекаем)', re.I)

def structure(raw):
    ingredients, steps = [], []
    for block in re.split(r'\n\s*\n', raw):
        block = block.strip()
        if not block or block.startswith(('#','‼','___','Реклама','http')): continue
        lines = [re.sub(r'^[•▫▪·📌\-]\s*','',s.strip()) for s in block.splitlines() if s.strip() and s.strip()!='⠀']
        if not lines: continue
        for line in lines:
            if len(line)<165 and (INGREDIENT.match(line) or re.match(r'^\d+(?:[.,]\d+)?\s*(?:г\b|гр\b|шт|ст\.|ч\.|мл|яйц|голов|плитк|ложк|лист|упак)',line,re.I)) and not ACTION.search(line) and not re.search(r'КБЖУ|ккал|порци|по желанию украс|не нужно',line,re.I):
                ingredients.append(line)
        if ACTION.search(block) and not re.search(r'пишите в|подпис|канал|ссылка|приготовьте|кто готовил|у меня никогда|обожаю|хочется готовить|каждый день|я готова есть',block,re.I):
            action_lines = [s for s in lines if ACTION.search(s) and not (len(s)<120 and INGREDIENT.match(s) and not re.search(r'\b(?:нарезать|смешать|добавить|выложить|натереть)\b',s,re.I))]
            for s in action_lines:
                s = re.sub(r'^\d+[.)⃣]?\s*','',s)
                steps.append(s)
    return list(dict.fromkeys(ingredients)), list(dict.fromkeys(steps))

def create(spec):
    name, source, cats = spec
    folder=ROOT/name
    raw=(folder/'recipe.txt').read_bytes().decode('utf-8-sig') if (folder/'recipe.txt').exists() else ''
    ident=hashlib.sha1(name.encode()).hexdigest()[:10]
    ingredients, steps=structure(raw)
    if name in CONTENT:
        a,b=CONTENT[name]; ingredients=a.split('|');steps=b.split('|')
    curated = SITE/'tools'/'curated.json'
    if curated.exists():
        correction=json.loads(curated.read_text(encoding='utf-8')).get(name,{})
        if 'ingredients' in correction: ingredients=correction['ingredients'].split('|') if correction['ingredients'] else []
        if 'steps' in correction: steps=correction['steps'].split('|') if correction['steps'] else []
    tags=[]; hay=(name+' '+' '.join(ingredients)).lower()
    hay=re.sub(r'яйц[оа]\s+курин[а-я]+','яйцо',hay)
    for tag,keys in [('Курица',['куриц','курин','цыплен']),('Рыба',['рыба','рыбы','минтай','тунец','тунцом','форель','сёмг','семг']),('Морепродукты',['кревет','снежный краб']),('Творог',['творог','творожн']),('Сыр',['сыр']),('Овощи',['брокколи','шпинат','овощ','свёкл','свекл']),('Картофель',['картоф']),('Аэрогриль',['аэрогрил']),('Духовка',['духовк','запек','выпек']),('Без мяса',['грушевый','мини-сметанники','кекс','панна-котта','ватрушки','маковые','сырники','зимний салат'])]:
        if any(k in hay for k in keys):tags.append(tag)
    tags=[t for t in tags if t not in ['Духовка','Аэрогриль']]
    preparation=' '.join(steps).lower()
    if 'аэрогрил' in preparation: tags.append('Аэрогриль')
    if 'духовк' in preparation or re.search(r'(?:запек|выпек).{0,55}(?:°|градус)',preparation): tags.append('Духовка')
    if not raw: tags.append('Рецепт в видео')
    photo=None;video=folder/'video.mp4'
    if video.exists():
        output=SITE/'images'/f'{ident}.jpg'
        if not output.exists():
            duration=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',str(video)],text=True).strip())
            subprocess.run(['ffmpeg','-v','error','-ss',str(duration*.82),'-i',str(video),'-frames:v','1','-vf','scale=720:-2','-q:v','4',str(output)],check=True)
        photo='images/'+output.name
    return {'id':ident,'title':name,'source':'https://vk.ru/'+(source if source.startswith('wall') else 'clip-'+source),'categories':cats.split(','),'tags':tags,'photo':photo,'ingredients':ingredients,'steps':steps,'original':raw}

if __name__=='__main__':
    (SITE/'images').mkdir(parents=True,exist_ok=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool: recipes=list(pool.map(create,SPECS))
    (SITE/'recipes.js').write_text('window.RECIPES = '+json.dumps(recipes,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
    print('Built',len(recipes),'recipes; photos:',sum(bool(r['photo']) for r in recipes))
    for r in recipes: print(r['title'],len(r['ingredients']),len(r['steps']))
